"""Writes the range tables of assemble/pystr.rs from this Python's unicodedata."""
import sys, unicodedata as u
props = [
 ("ALPHA", "`str.isalpha`: general categories Lu, Ll, Lt, Lm, Lo.", lambda c: c.isalpha()),
 ("DIGIT", "`str.isdigit`: Numeric_Type Digit or Decimal.", lambda c: c.isdigit()),
 ("DECIMAL", "`str.isdecimal`, and what `re`'s `\\d` matches: general category Nd.", lambda c: c.isdecimal()),
 ("SPACE", "`str.isspace`: what `str.strip()`, `str.split()` and `re`'s `\\s` treat as white space.", lambda c: c.isspace()),
 ("WIDE", "`unicodedata.east_asian_width` W or F.", lambda c: u.east_asian_width(c) in "WF"),
 ("RTL", "`unicodedata.bidirectional` R or AL (`rtl.is_rtl`).", lambda c: u.bidirectional(c) in ("R", "AL")),
 ("LTR", "`unicodedata.bidirectional` L, EN or AN (`rtl._is_ltr`).", lambda c: u.bidirectional(c) in ("L", "EN", "AN")),
 ("NUMBER", "`unicodedata.bidirectional` EN or AN.", lambda c: u.bidirectional(c) in ("EN", "AN")),
 ("MARK", "`unicodedata.category` Mn or Me (`rtl.clusters`).", lambda c: u.category(c) in ("Mn", "Me")),
]
out = ["// ---- generated tables ----", f"// Generated by gen_pystr.py from Python {sys.version.split()[0]}'s unicodedata {u.unidata_version}.",
       "// Inclusive code point ranges, ascending.", ""]
for name, doc, f in props:
    rs = []; start = None
    for cp in range(0x110000):
        v = False if 0xD800 <= cp <= 0xDFFF else f(chr(cp))
        if v and start is None: start = cp
        if not v and start is not None: rs.append((start, cp - 1)); start = None
    if start is not None: rs.append((start, 0x10FFFF))
    out.append(f"/// {doc}")
    out.append("#[rustfmt::skip]")
    out.append(f"pub(super) const {name}: &[(u32, u32)] = &[")
    line = "   "
    for a, b in rs:
        item = f" (0x{a:X}, 0x{b:X}),"
        if len(line) + len(item) > 99:
            out.append(line); line = "   "
        line += item
    out.append(line)
    out.append("];")
    out.append("")
open(sys.argv[1], "w").write("\n".join(out))
